import{_ as s,l as o,o as e,c as n,v as t,p as l,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"磁盘调度","description":"","frontmatter":{"title":"磁盘调度","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/disk-sched.md","filePath":"cs/disk-sched.md","lastUpdated":1789023840000}'),h={name:"cs/disk-sched.md"};function S(m,a,A,_,u,C){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="磁盘调度" tabindex="-1">磁盘调度 <a class="header-anchor" href="#磁盘调度" aria-label="Permalink to &quot;磁盘调度&quot;">​</a></h1><div class="epigraph"><p>旋转磁盘上，请求顺序决定寻道时间；电梯算法让磁头单向扫过，避免饥饿与来回抖动。</p><footer>—— 据 Silberschatz et al., Operating System Concepts；Teorey and Pinkerton, A comparative analysis of disk scheduling policies, 1972 整理</footer></div><p><a href="/cs/setuid-sticky">上一课</a>产生一串读盘与回写请求。若按到达序（FCFS）送给磁头，短寻道与长寻道混排，平均等待差。缺口是<strong>磁盘调度</strong>：在可旋转介质上对块请求排序。本课以寻道为主，闪存只作边界对照。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>机械盘的时间在寻道与旋转，不在总线。<a href="/cs/scheduling-metrics">调度指标</a>换成：平均寻道、公平（内磁道不要饿死）。SSTF 总选最近请求，易饿外圈。SCAN/LOOK（电梯）扫到头再反向；C-SCAN 只单向服务，回来不服务，公平些。缺口不是 inode，而是请求队列上的排序。</p><p>本课不把 NCQ 与盘片内部重排的固件当主干实现。</p><p><span class="marginnote">闪存没有寻道，调度目标变成擦除块、磨损与并行通道。教学仍用机械电梯讲「请求顺序是资源」。SSD 上盲目 SCAN 无意义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>维护按柱面排序的待服务队列。LOOK：向当前方向走到最远请求再折返。内核把缓冲回写与用户读混在同一队列时，要避免写风暴挡住读——这是策略，不是新硬件。设备完成仍走<a href="/cs/interrupt-bottom-half">中断下半部</a>，完成的请求从队列消失。</p>',9)),(e(),l(p,null,{default:r(()=>[c(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%84%8F%E9%A1%B5%E4%B8%8E%E8%AF%BB%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20SORT%5B%22%E6%8C%89%E6%9F%B1%E9%9D%A2%E6%8E%92%E5%BA%8F%22%5D%0A%20%20SORT%20--%3E%20SCAN%5B%22SCAN%2FLOOK%20%E6%9C%8D%E5%8A%A1%22%5D%0A%20%20SCAN%20--%3E%20IRQ%5B%22%E5%AE%8C%E6%88%90%E4%B8%AD%E6%96%AD%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>磁盘调度是 I/O 版的电梯：与 CPU 的 CFS 不同，这里优化的是机械移动，不是虚拟时间。但它同样能制造饥饿，所以 SSTF 不是默认正确答案。与页置换一起：回写时机由脏页策略决定，<strong>顺序</strong>由本课决定。错误地把随机脏页立刻刷盘，会把电梯打成随机寻道。</p><p>块号与柱面的映射由驱动与盘片几何（或 LBA 后的近似）给出；教学用一维柱面足够。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 RAID 条带的全部调度，不把网络盘的 RTT 当寻道。也不声称 Linux CFQ/BFQ/mq-deadline 与 SCAN 同构；现代多队列是另一实现。闪存与持久内存把「电梯」从主干里降为历史对照。</p><p>旋转延迟与传输时间在教学模型里常并入「服务时间」；电梯主要打寻道这一项。</p><p>闪存翻译层自己会重排，主机调度器看到的 LBA 顺序不等于芯片顺序。</p><p>后课默认：块请求可以排序后发给设备。多种文件系统如何共用同一套 <code>read</code> 路径，下一课虚拟文件系统。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>机械盘上顺序就是性能；LOOK/C-SCAN 权衡平均与饥饿。</li><li>闪存目标不同，不要把 SCAN 当普适。</li><li>统一文件接口是 VFS 的缺口。</li><li>出处：Teorey and Pinkerton, 1972；Silberschatz et al., <em>OSC</em>；Tanenbaum <em>MOS</em>。</li></ul>',10))])}const T=s(h,[["render",S]]);export{f as __pageData,T as default};
